const items = $input.all();
const priority = ['zero-day','zero day','actively exploited','exploited in the wild','critical','ransomware','breach','cve-','rce','backdoor','supply chain','nation-state','apt','malware campaign'];
const general = ['vulnerability','exploit','malware','phishing','cyberattack','patch','trojan','spyware','ddos','data leak','hacked','compromise','threat actor','botnet','credential','infostealer'];
const cutoff = Date.now() - 24*60*60*1000;
const DOM = [['thehackernews','The Hacker News'],['krebsonsecurity','Krebs on Security'],['bleepingcomputer','BleepingComputer'],['darkreading','Dark Reading'],['securityweek','SecurityWeek'],['cisa.gov','CISA'],['cisa.','CISA'],['zerodayinitiative','Zero Day Initiative']];
const seen = new Set();
let rel = items.map(it => {
  const j = it.json;
  const title = (j.title || '').toString();
  const desc = (j.contentSnippet || j.content || j.description || '').toString();
  const ds = j.isoDate || j.pubDate;
  const dt = ds ? new Date(ds).getTime() : 0;
  const text = (title + ' ' + desc).toLowerCase();
  const blob = JSON.stringify(j).toLowerCase();
  let source = 'Cyber Desk';
  for (const [d, n] of DOM) {
    if (blob.includes(d)) { source = n; break; }
  }
  return { title, desc, dt, isPrio: priority.some(k => text.includes(k)), isGen: general.some(k => text.includes(k)), source };
})
.filter(x => x.title && (x.dt >= cutoff || x.dt === 0) && (x.isPrio || x.isGen))
.filter(x => {
  const k = x.title.toLowerCase().slice(0, 60);
  if (seen.has(k)) return false;
  seen.add(k);
  return true;
});
rel.sort((a, b) => (b.isPrio - a.isPrio) || (b.dt - a.dt));
return rel.slice(0, 4).map(x => ({
  json: {
    title: x.title,
    content: x.desc.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 500),
    source: x.source
  }
}));

const src = $('Code-Prepare-TTS-Payload').first().json;
const out = [];
for (const item of $input.all()){
  const j = item.json;
  const b64 = j.audioContent || j.audio_base64;
  const align = j.alignment || j.normalized_alignment;
  let audioDuration = 0;
  if (align && Array.isArray(align.character_end_times_seconds) && align.character_end_times_seconds.length){ audioDuration = align.character_end_times_seconds[align.character_end_times_seconds.length-1]; }
  if (!audioDuration){ const w = (src.stories||[]).reduce((a,s)=>a+(s.words||0),0); audioDuration = Math.max(20, Math.round(w/2.6)); }
  if (b64 && typeof b64==='string' && b64.length){
    const buffer = Buffer.from(b64,'base64');
    item.binary = { data: { mimeType:'audio/mpeg', data: buffer.toString('base64') } };
    item.json = { fileName: `cyber_${src.currentDateFormatted}_${Date.now()}.mp3`, combinedTitle: src.combinedTitle, currentDateFormatted: src.currentDateFormatted, audioDuration, stories: src.stories, fullScriptForCreatomate: src.fullScriptForCreatomate };
  } else {
    item.json.error = 'Audio content empty';
  }
  out.push(item);
}
return out;

const outs = $input.all();
const filt = $('Filter - Latest & Relevant').all();
const parse = c => { try { const m = String(c).match(/\{[\s\S]*\}/); return m ? JSON.parse(m[0]) : null; } catch(e){ return null; } };
const clean = t => String(t).replace(/[<>]/g,'').trim();
const stories = []; const scripts = [];
for (let i=0;i<outs.length;i++){
  const content = (outs[i].json.message && outs[i].json.message.content) || outs[i].json.content || outs[i].json.text || '';
  const p = parse(content) || {};
  const f = filt[i] ? filt[i].json : {};
  const script = clean(p.script || content);
  if (!script) continue;
  scripts.push(script);
  const whatHappened = clean(p.whatHappened || p.why || f.content || '').slice(0, 145);
  const whoAffected = clean(p.whoAffected || `Systems and users running software covered in this ${f.source || 'security'} alert.`).slice(0, 120);
  const howToStaySafe = clean(p.howToStaySafe || p.action || 'Apply the latest security patch immediately and audit system access logs.').slice(0, 140);
  const severity = clean(p.severity || 'HIGH RISK • SECURITY ALERT').toUpperCase().slice(0, 32);
  stories.push({
    headline: clean(p.headline || f.title || 'Security Alert').slice(0, 68),
    source: clean(f.source || 'Security'),
    severity,
    whatHappened,
    whoAffected,
    howToStaySafe,
    why: whatHappened,
    action: howToStaySafe,
    script,
    words: script.split(/\s+/).filter(Boolean).length
  });
}
if (!stories.length) throw new Error('No cyber stories to build');
const now = new Date();
const date = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
const cta = 'Follow byte f y i for daily cyber security alerts. Subscribe and stay one step ahead.';
const ctaWords = cta.split(/\s+/).filter(Boolean).length;
const voiceover = scripts.join('  ') + '  ' + cta;
const ytTitle = clean(`Cyber Security News ${date} | ${stories.length} Threats You Must Know Today`);
const ytDescription = clean(`Today's top cybersecurity threats (${date}):\n\n` + stories.map((s,i)=>`${i+1}. ${s.headline} (${s.source})\n   • What happened: ${s.whatHappened}\n   • Who is affected: ${s.whoAffected}\n   • How to stay safe: ${s.howToStaySafe}`).join('\n\n') + `\n\nStay secure and FOLLOW @bytefyi for daily cyber news.\n\n#CyberSecurity #InfoSec #Hacking #DataBreach #Ransomware #ZeroDay #Shorts #TechNews #CyberAwareness`);
const ytTags = ['cybersecurity','cyber security news','infosec','hacking news','data breach','ransomware','zero day','vulnerability','tech news','daily cyber news'].join(',');
const igCaption = `🔒 Cyber News ${date}\n\n` + stories.map((s,i)=>`${i+1}. ${s.headline}\n   ✅ Fix: ${s.howToStaySafe}`).join('\n\n') + `\n\nFollow @bytefyi for daily cyber alerts 🛡️\n\n#CyberSecurity #InfoSec #Hacking #DataBreach #Ransomware #Shorts`;
const combinedTitle = `${date} - Cyber News: ${stories.slice(0,3).map(s=>s.headline).join(' | ')}`.slice(0,190);
return [{ json: { fullScriptForCreatomate: voiceover, stories, ctaWords, combinedTitle, currentDateFormatted: date, ytTitle, ytDescription, ytTags, igCaption } }];

const d = $('Code-Prepare-TTS-Payload').first().json;
const stories = d.stories || [];
const date = d.currentDateFormatted || '';
const audioUrl = $json.mediaLink;
const dur = Math.max(12, ($('Move & Rename Binary Data').first().json.audioDuration) || 45);
const ctaWords = d.ctaWords || 14;

const F = 'Montserrat', BG = '#050B16', RED = '#E11D48', CYAN = '#38BDF8', AMBER = '#FBBF24', EMERALD = '#10B981', WHITE = '#FFFFFF', SLATE = '#94A3B8';
const RECT = 'M 0 0 L 100 0 L 100 100 L 0 100 Z';
const BGVID = 'https://videos.pexels.com/video-files/39463971/16809077_1080_1920_30fps.mp4';

const els = [];
const fade = [{ type: 'fade', duration: 0.25 }];
const txt = o => els.push(Object.assign({ type: 'text', font_family: F, fill_color: WHITE, x_alignment: '50%', y_alignment: '50%', text_alignment: 'center' }, o));
const box = o => els.push(Object.assign({ type: 'shape', path: RECT }, o));

const total = Math.max(12, Math.ceil(dur * 10) / 10);
const storyWords = stories.reduce((a, s) => a + (s.words || 1), 0) || 1;
const grand = storyWords + ctaWords;

// Static Masthead below Instagram profile overlay (y=285px, spans 230px..340px — leaves 0..220px clear for IG username/audio)
box({ x: '50%', y: '105px', width: '100%', height: '210px', fill_color: '#030710E6', time: 0, duration: total });
box({ x: '50%', y: '285px', width: '90%', height: '110px', border_radius: '20px', fill_color: '#0B1528F5', border_color: '#1E3A5F', border_width: '2px', time: 0, duration: total });
box({ x: '16.5%', y: '285px', width: '17%', height: '74px', border_radius: '14px', fill_color: RED, time: 0, duration: total });
txt({ text: 'CYBER\nNEWS', x: '16.5%', y: '285px', width: '16%', font_size: '23px', font_weight: '800', line_height: '105%', fill_color: WHITE, time: 0, duration: total });
txt({ text: 'DAILY THREAT BRIEFING', x: '52%', y: '266px', width: '48%', font_size: '28px', font_weight: '800', fill_color: WHITE, text_alignment: 'left', time: 0, duration: total });
txt({ text: `BYTEFYI SECURITY DESK • ${date}`, x: '52%', y: '304px', width: '48%', font_size: '19px', font_weight: '600', fill_color: CYAN, text_alignment: 'left', time: 0, duration: total });
box({ x: '85.5%', y: '285px', width: '14%', height: '64px', border_radius: '14px', fill_color: '#112240', border_color: CYAN, border_width: '1.5px', time: 0, duration: total });

let cum = 0;
const nStories = Math.max(1, stories.length);
stories.forEach((s, i) => {
  const start = (cum / grand) * total;
  const d2 = Math.max(2, (s.words / grand) * total);
  cum += s.words || 1;

  // Step counter in masthead (e.g. "3 / 4")
  txt({ text: `${i + 1} / ${nStories}`, x: '85.5%', y: '285px', width: '13%', font_size: '28px', font_weight: '800', fill_color: CYAN, time: start, duration: d2 });

  // Segmented Story Progress Bar (y=362px)
  for (let k = 0; k < nStories; k++) {
    const segW = (90 - (nStories - 1) * 1.8) / nStories;
    const segX = 5 + segW / 2 + k * (segW + 1.8);
    const segCol = k === i ? RED : (k < i ? '#2563EB' : '#1E293B');
    box({ x: `${segX.toFixed(2)}%`, y: '362px', width: `${segW.toFixed(2)}%`, height: '8px', border_radius: '4px', fill_color: segCol, time: start, duration: d2 });
  }

  // Main Intelligence Card (y=870px, height=960px -> spans 390px to 1350px)
  box({ x: '50%', y: '870px', width: '90%', height: '960px', border_radius: '28px', fill_color: '#081121FA', border_color: '#1E3A5F', border_width: '2px', time: start, duration: d2, animations: fade });
  box({ x: '50%', y: '393px', width: '90%', height: '6px', border_radius: '3px', fill_color: RED, time: start, duration: d2 });

  // Top Severity Badge (Left) + Source Pill (Right)
  box({ x: '29%', y: '442px', width: '40%', height: '50px', border_radius: '12px', fill_color: '#3B0A18', border_color: RED, border_width: '1.5px', time: start, duration: d2 });
  txt({ text: String(s.severity || `THREAT ${i + 1} OF ${nStories} • HIGH RISK`).toUpperCase(), x: '29%', y: '442px', width: '38%', font_size: '20px', font_weight: '800', fill_color: '#FDA4AF', time: start, duration: d2 });

  box({ x: '72%', y: '442px', width: '38%', height: '50px', border_radius: '12px', fill_color: '#0F1D36', border_color: '#F59E0B88', border_width: '1.5px', time: start, duration: d2 });
  txt({ text: `SOURCE: ${String(s.source || 'CYBER DESK').toUpperCase()}`, x: '72%', y: '442px', width: '36%', font_size: '19px', font_weight: '700', fill_color: AMBER, time: start, duration: d2 });

  // Clear Left-Aligned Headline
  txt({ text: String(s.headline || 'Critical Security Alert'), x: '50%', y: '548px', width: '82%', font_size: '42px', font_weight: '800', line_height: '116%', fill_color: WHITE, text_alignment: 'left', time: start, duration: d2, animations: fade });

  // Section 1: 1. WHAT HAPPENED
  box({ x: '50%', y: '715px', width: '82%', height: '185px', border_radius: '18px', fill_color: '#0D1B33', border_color: '#1E3A5F', border_width: '1.5px', time: start, duration: d2 });
  box({ x: '9.5%', y: '715px', width: '8px', height: '185px', border_radius: '4px', fill_color: CYAN, time: start, duration: d2 });
  txt({ text: '1. WHAT HAPPENED', x: '51%', y: '652px', width: '76%', font_size: '21px', font_weight: '800', fill_color: CYAN, text_alignment: 'left', time: start, duration: d2 });
  txt({ text: String(s.whatHappened || s.why || ''), x: '51%', y: '732px', width: '76%', font_size: '27px', font_weight: '600', line_height: '122%', fill_color: WHITE, text_alignment: 'left', time: start, duration: d2, animations: fade });

  // Section 2: 2. WHO IS AFFECTED
  box({ x: '50%', y: '925px', width: '82%', height: '175px', border_radius: '18px', fill_color: '#0D1B33', border_color: '#1E3A5F', border_width: '1.5px', time: start, duration: d2 });
  box({ x: '9.5%', y: '925px', width: '8px', height: '175px', border_radius: '4px', fill_color: AMBER, time: start, duration: d2 });
  txt({ text: '2. WHO IS AFFECTED', x: '51%', y: '866px', width: '76%', font_size: '21px', font_weight: '800', fill_color: AMBER, text_alignment: 'left', time: start, duration: d2 });
  txt({ text: String(s.whoAffected || 'Users and organizations running unpatched versions.'), x: '51%', y: '942px', width: '76%', font_size: '27px', font_weight: '600', line_height: '122%', fill_color: WHITE, text_alignment: 'left', time: start, duration: d2, animations: fade });

  // Section 3: 3. HOW TO STAY SAFE
  box({ x: '50%', y: '1175px', width: '82%', height: '265px', border_radius: '20px', fill_color: '#06281E', border_color: EMERALD, border_width: '2px', time: start, duration: d2, animations: fade });
  box({ x: '28%', y: '1082px', width: '34%', height: '42px', border_radius: '10px', fill_color: EMERALD, time: start, duration: d2 });
  txt({ text: '3. HOW TO STAY SAFE', x: '28%', y: '1082px', width: '32%', font_size: '20px', font_weight: '800', fill_color: '#022C22', time: start, duration: d2 });
  txt({ text: String(s.howToStaySafe || s.action || 'Update immediately to the latest patched version.'), x: '50%', y: '1198px', width: '76%', font_size: '29px', font_weight: '700', line_height: '124%', fill_color: '#ECFDF5', text_alignment: 'left', time: start, duration: d2 });

  // Live Synced Voiceover Transcript Bar (y=1475px, height=180px)
  box({ x: '50%', y: '1475px', width: '90%', height: '180px', border_radius: '22px', fill_color: '#0B1528F2', border_color: '#38BDF866', border_width: '1.5px', time: start, duration: d2 });
  txt({ text: 'LIVE VOICEOVER TRANSCRIPT', x: '50%', y: '1415px', width: '82%', font_size: '19px', font_weight: '800', fill_color: CYAN, text_alignment: 'left', time: start, duration: d2 });
  txt({ text: `"${String(s.script || '')}"`, x: '50%', y: '1492px', width: '82%', font_size: '25px', font_weight: '600', line_height: '122%', fill_color: '#E2E8F0', text_alignment: 'left', time: start, duration: d2 });
});

// Outro Card
const cStart = (storyWords / grand) * total;
const cDur = Math.max(1.5, total - cStart);
txt({ text: 'DONE', x: '85.5%', y: '285px', width: '13%', font_size: '24px', font_weight: '800', fill_color: EMERALD, time: cStart, duration: cDur });
box({ x: '50%', y: '870px', width: '90%', height: '960px', border_radius: '28px', fill_color: '#081121FA', border_color: '#1E3A5F', border_width: '2px', time: cStart, duration: cDur, animations: fade });
box({ x: '50%', y: '393px', width: '90%', height: '6px', border_radius: '3px', fill_color: RED, time: cStart, duration: cDur });
txt({ text: 'STAY ONE STEP AHEAD', x: '50%', y: '640px', width: '82%', font_size: '54px', font_weight: '800', fill_color: WHITE, time: cStart, duration: cDur, animations: fade });
box({ x: '50%', y: '840px', width: '78%', height: '120px', border_radius: '22px', fill_color: RED, time: cStart, duration: cDur, animations: fade });
txt({ text: 'FOLLOW @bytefyi', x: '50%', y: '840px', width: '74%', font_size: '50px', font_weight: '800', fill_color: WHITE, time: cStart, duration: cDur });
txt({ text: 'DAILY CYBER BRIEFING • EVERY MORNING', x: '50%', y: '1010px', width: '82%', font_size: '30px', font_weight: '700', fill_color: AMBER, time: cStart, duration: cDur, animations: fade });
txt({ text: 'Save & share this briefing with your security team', x: '50%', y: '1100px', width: '80%', font_size: '28px', font_weight: '600', fill_color: SLATE, time: cStart, duration: cDur });

// Audio layer
els.push({ type: 'audio', name: 'VO', source: audioUrl, time: 0, duration: total });

// Footer inside safe zone (y=1610px, well above Instagram bottom bar)
txt({ text: '@bytefyi  •  Daily Cyber Threat Intelligence', x: '50%', y: '1610px', width: '80%', font_size: '24px', font_weight: '600', fill_color: SLATE, time: 0, duration: total });

// Background Layers
els.unshift({ type: 'shape', path: RECT, x: '50%', y: '50%', width: '100%', height: '100%', fill_color: '#050B16D8', time: 0, duration: total });
els.unshift({ type: 'video', source: BGVID, x: '50%', y: '50%', width: '100%', height: '100%', fit: 'cover', loop: true, volume: '0%', time: 0, duration: total });

return { json: { output_format: 'mp4', width: 1080, height: 1920, frame_rate: 30, fill_color: BG, duration: total, elements: els } };
